-- krxzoski / Prison Life only (place 155615604)
-- V: show/hide. Unload is on the Dashboard.
if game.PlaceId ~= 155615604 then
    warn('[krxzoski] This build is for Prison Life only (155615604).')
    return
end


-- KRXZOSKI Goku intro: plays before the Prison Life hub initializes.
-- Uses the same image, music, and title as KRXZOSKI_GOKU_BRANDED.
local function playKrxzoskiIntro()
    local ok, err = pcall(function()
        local Players = game:GetService("Players")
        local TweenService = game:GetService("TweenService")
        local SoundService = game:GetService("SoundService")
        local player = Players.LocalPlayer
        if not player then return end

        local playerGui = player:WaitForChild("PlayerGui", 10)
        if not playerGui then return end

        local gui = Instance.new("ScreenGui")
        gui.Name = "KRXZOSKI_Goku_Intro"
        gui.IgnoreGuiInset = true
        gui.ResetOnSpawn = false
        gui.DisplayOrder = 100000
        gui.Parent = playerGui

        local background = Instance.new("ImageLabel")
        background.Name = "GokuBackground"
        background.Size = UDim2.fromScale(1, 1)
        background.Position = UDim2.fromScale(0, 0)
        background.BackgroundColor3 = Color3.fromRGB(5, 7, 24)
        background.BorderSizePixel = 0
        background.Image = "rbxassetid://133057178547287"
        background.ScaleType = Enum.ScaleType.Crop
        background.ImageTransparency = 1
        background.Parent = gui

        local title = Instance.new("TextLabel")
        title.Name = "KRXZOSKI_Title"
        title.BackgroundTransparency = 1
        title.AnchorPoint = Vector2.new(0.5, 0.5)
        title.Position = UDim2.fromScale(0.5, 0.76)
        title.Size = UDim2.new(0.92, 0, 0, 92)
        title.Font = Enum.Font.GothamBlack
        title.Text = "KRXZOSKI MEJOR PANEL DO MOMENTO"
        title.TextColor3 = Color3.fromRGB(255, 255, 255)
        title.TextScaled = true
        title.TextWrapped = true
        title.TextTransparency = 1
        title.TextStrokeColor3 = Color3.fromRGB(105, 45, 255)
        title.TextStrokeTransparency = 0.12
        title.Parent = gui

        local limit = Instance.new("UITextSizeConstraint")
        limit.MinTextSize = 18
        limit.MaxTextSize = 42
        limit.Parent = title

        local sound = Instance.new("Sound")
        sound.Name = "KRXZOSKI_Intro_Music"
        sound.SoundId = "rbxassetid://93174457535427"
        sound.Volume = 0.5
        sound.Looped = false
        sound.Parent = SoundService

        TweenService:Create(background, TweenInfo.new(1.1), {
            ImageTransparency = 0
        }):Play()
        TweenService:Create(title, TweenInfo.new(1.1), {
            TextTransparency = 0
        }):Play()

        sound:Play()
        task.wait(15)

        local fadeInfo = TweenInfo.new(0.8)
        TweenService:Create(background, fadeInfo, {
            ImageTransparency = 1
        }):Play()
        TweenService:Create(title, fadeInfo, {
            TextTransparency = 1
        }):Play()
        TweenService:Create(sound, fadeInfo, {
            Volume = 0
        }):Play()
        task.wait(0.85)

        sound:Stop()
        sound:Destroy()
        gui:Destroy()
    end)

    if not ok then
        warn("[krxzoski] Intro skipped: " .. tostring(err))
    end
end

playKrxzoskiIntro()

