local function drawIcon(image,lines)
 if typeof(image)~='Instance' or not image:IsA('ImageLabel') then return end
 image.Image=''
 local strokes={}
 for _,line in ipairs(lines) do
  local dx,dy=line[3]-line[1],line[4]-line[2]
  local stroke=Instance.new('Frame');stroke.Name='Stroke';stroke.BorderSizePixel=0;stroke.AnchorPoint=Vector2.new(0.5,0.5)
  stroke.Position=UDim2.fromScale((line[1]+line[3])/40,(line[2]+line[4])/40)
  stroke.Size=UDim2.new(math.sqrt(dx*dx+dy*dy)/20,0,0,1.5);stroke.Rotation=math.deg(math.atan2(dy,dx));stroke.BackgroundColor3=image.ImageColor3;stroke.Parent=image
  table.insert(strokes,stroke)
 end
 table.insert(Window._connections,image:GetPropertyChangedSignal('ImageColor3'):Connect(function()
  for _,stroke in ipairs(strokes) do stroke.BackgroundColor3=image.ImageColor3 end
 end))
end
local function makeTab(key,name)
 local tab=Window:CreateTab({Name=name or tabLabels[key] or key,Icon='hexagon'})
 local lines=iconLines[key] or iconLines.Home
 drawIcon(tab._icon,lines)
 if typeof(tab._page)=='Instance' then
  for _,item in ipairs(tab._page:GetChildren()) do if item:IsA('ImageLabel') then drawIcon(item,lines) end end
 end
 return tab
end
