function bridge:Detection(player,reason)
 local labels={speed='Unusual movement speed',teleport='Sudden position change',highjump='Unusual jump height',['phase/noclip']='Possible collision bypass'}
 local detail=labels[reason] or 'Unusual character state'
 local name=player.DisplayName==player.Name and player.Name or player.DisplayName..' (@'..player.Name..')'
 table.insert(activity,1,{Text=name,Value=detail})
 if #activity>6 then table.remove(activity) end
 local now=os.clock();local last=activityLast[player.UserId]
 if activityAlerts and (not last or now-last>=20) then
  activityLast[player.UserId]=now
  self:Notify('Activity notice',name..' · '..detail..'. Unconfirmed.',4,'Warning')
 end
end
function bridge:Notify(title,message,duration,kind)
 if not self.Alive or title=='Finished Loading' then return end
 local function tidy(value)
  return tostring(value or ''):gsub('<[^>]->',''):gsub('[Vv][Aa][Pp][Ee]','krxzoski'):gsub('[Rr][Ii][Gg][Hh][Tt]%s*[Ss][Hh][Ii][Ff][Tt]','V'):gsub('[Rr][Ii][Gg][Hh][Tt]%s*[Cc][Oo][Nn][Tt][Rr][Oo][Ll]','V')
 end
 title=tidy(title):sub(1,48);message=tidy(message):sub(1,260)
 local key=title..message;local now=os.clock()
 if recentNotice[key] and now-recentNotice[key]<2 then return end
 for id,time in pairs(recentNotice) do if now-time>5 then recentNotice[id]=nil end end
 recentNotice[key]=now
 local types={alert='Error',warning='Warning',success='Success',Error='Error',Warning='Warning',Success='Success'}
 Library:Notify({Title=title=='' and 'krxzoski' or title,Content=message,Duration=math.clamp(tonumber(duration) or 4,2,8),Type=types[kind] or 'Info'})
end
