local sync, connections={},{}
local function guard(fn)
 return function(...)
  if not bridge.Alive then return end
  local ok,err=pcall(fn,...);if not ok then bridge:Fail(err) end
 end
end
local function toggle(group,name,obj,field)
 field=field or 'Enabled'
 local control=group:CreateToggle({Name=name,CurrentValue=obj[field]==true,Callback=guard(function(v)
  if obj[field]~=v then obj:Toggle() end
 end)})
 table.insert(sync,function() control:Set(obj[field]==true,true) end)
 return control
end
local keyNames={}
for _,key in ipairs(Enum.KeyCode:GetEnumItems()) do keyNames[key.Name:lower()]=key.Name end
local keyAliases={ctrl='LeftControl',control='LeftControl',shift='LeftShift',alt='LeftAlt',spacebar='Space',esc='Escape',enter='Return',del='Delete'}
local function parseKeybind(text)
 local keys={}
 for token in tostring(text):gmatch('[^+]+') do
  local name=token:match('^%s*(.-)%s*$'):lower()
  if name~='' then
   local key=keyNames[name] or keyAliases[name]
   assert(key and key~='Unknown','Unknown key: '..token)
   if not table.find(keys,key) then table.insert(keys,key) end
  end
 end
 return keys
end

local function input(group,name,value,fn)
 return group:CreateInput({Name=name,CurrentValue=tostring(value or ''),Callback=guard(fn)})
end
local function addOption(group,name,o)
 local p=o.BVCProps or {};local c
 if o.Type=='Toggle' then c=toggle(group,name,o)
 elseif o.Type=='Slider' then
  c=group:CreateSlider({Name=name,Range={p.Min or 0,p.Max or o.Max or 100},Increment=1/(p.Decimal or 1),CurrentValue=o.Value,Callback=guard(function(v) o:SetValue(v,nil,true) end)})
 elseif o.Type=='Dropdown' then
  c=group:CreateDropdown({Name=name,Options=p.List or {},CurrentOption=o.Value,AllowNone=false,Callback=guard(function(v) o:SetValue(type(v)=='table' and v[1] or v) end)})
 elseif o.Type=='TextBox' then c=input(group,name,o.Value,function(v) o:SetValue(v,true) end)
 elseif o.Type=='TextList' then
  local enabledList
  c=input(group,name,table.concat(o.List or {},', '),function(text)
   local list={};for v in text:gmatch('[^,]+') do v=v:match('^%s*(.-)%s*$');if v~='' then table.insert(list,v) end end
   o.List=list;o.ListEnabled=table.clone(list);o:ChangeValue()
   if enabledList then enabledList:SetOptions(list);enabledList:Set(list,true) end
  end)
  enabledList=group:CreateDropdown({Name=name..' / Enabled',Options=o.List or {},CurrentOption=o.ListEnabled or {},MultipleOptions=true,Callback=guard(function(v)
   o.ListEnabled=type(v)=='table' and v or {v};o:ChangeValue()
  end)})
 elseif o.Type=='ColorSlider' then
  c=group:CreateColorPicker({Name=name,CurrentValue=Color3.fromHSV(o.Hue,o.Sat,o.Value),Callback=guard(function(v)
   local h,s,value=v:ToHSV();o:SetValue(h,s,value,o.Opacity)
  end)})
  group:CreateSlider({Name=name..' / Opacity',Range={0,1},Increment=0.01,CurrentValue=o.Opacity,Callback=guard(function(v) o:SetValue(o.Hue,o.Sat,o.Value,v) end)})
  toggle(group,name..' / Rainbow',o,'Rainbow')
 elseif o.Type=='Targets' then
  for _,k in ipairs({'Players','NPCs','Invisible','Walls'}) do if o[k] then toggle(group,name..' / '..k,o[k]) end end
 else error('Unsupported control '..tostring(o.Type)..' in '..name) end
 if c and o.Object then table.insert(sync,function() c:SetVisible(o.Object.Visible) end) end
end
function bridge:Attach(vape)
 self.Engine=vape
 local registry=table.clone(shared.BVCPrisonModules or {})
 local movement={'Speed','Fly','HighJump','LongJump','Phase','Spider','Swim','MouseTP','TargetStrafe','AntiFall','Gravity','Parkour','Wallhop'}
 local registered={}
 for _,entry in ipairs(registry) do registered[entry.name]=true end
 for _,name in ipairs(movement) do
  local module=vape.Modules[name]
  if module and not registered[name] then
   table.insert(registry,{name=name,category='Player',module=module})
   registered[name]=true
  end
 end
 local tabs={};local counts={}
 local sections={
  {'Combat','crosshair',{'SilentAim','TriggerBot','Killaura','AutoArrest','AutoTaze'}},
  {'Weapons','swords',{'GunModifications','AutoReload','AutoDetonate'}},
  {'Defense','shield',{'AntiFling','AntiInvisible','AntiKillPlane','AntiRiotShield','AntiTaze','FenceGodmode'}},
  {'Player','user',{'Speed','Fly','HighJump','LongJump','Phase','Spider','Swim','MouseTP','TargetStrafe','AntiFall','Gravity','Parkour','Wallhop','AutoReset','NoJumpCooldown','AutoTeam'}},
  {'Vehicles','car',{'VehicleFly','VehicleSpeed','VehicleWallbang'}},
  {'Inventory','backpack',{'AutoArmor','AutoHeal','AutoHotbar','AutoPickup'}},
  {'Visuals','eye',{'C4ESP','CameraPhase','KillNotifications','Crosshair','Viewmodel'}},
  {'Effects & Sounds','sparkles',{'HitEffects','DamageIndicator','BulletTracers','HitSound','KillSound'}},
  {'Player Aura','orbit',{'PlayerAura'}},
  {'Character Skins','user-round',{'CharacterSkin'}},
  {'Utility','wrench',{'FlingExploit','AutoToxic','CheatDetector','Disabler'}}
 }
 local destinations={}
 for _,section in ipairs(sections) do
  local name=section[1]
  tabs[name]=makeTab(name);counts[name]=0
  for _,moduleName in ipairs(section[3]) do destinations[moduleName]=name end
 end
 for _,entry in ipairs(registry) do
  local destination=destinations[entry.name] or 'Utility'
  local tab=tabs[destination];counts[destination]=counts[destination]+1
  local labels={CheatDetector='Activity Monitor',GunModifications='Gun Mods',AutoReload='Auto Reload',AutoDetonate='Auto Detonate'}
  local label=labels[entry.name] or entry.name
  local group=tab[counts[destination]%2==1 and 'AddLeftGroupbox' or 'AddRightGroupbox'](tab,{Name=label})
  toggle(group,label,entry.module)
  local names={};for name in pairs(entry.module.Options or {}) do table.insert(names,name) end;table.sort(names)
  for _,name in ipairs(names) do addOption(group,name,entry.module.Options[name]) end
  if type(entry.module.Preview)=='function' then
   group:CreateButton({Name=entry.name=='CharacterSkin' and 'Apply character' or 'Preview effect',Callback=guard(function() entry.module:Preview() end)})
   if entry.name=='CharacterSkin' then group:CreateButton({Name='Restore my character',Callback=guard(function() if entry.module.Enabled then entry.module:Toggle() end end)}) end
  end
  if entry.name=='HitSound' or entry.name=='KillSound' then
   group:CreateDropdown({Name='Sound preset',Options={'Custom','Pop','Thud','Chime'},CurrentOption='Custom',AllowNone=false,Callback=guard(function(value)
    local choice=type(value)=='table' and value[1] or value
    if choice=='Custom' then return end
    assert(type(getcustomasset)=='function','Sound presets need getcustomasset support')
    local path='krxzoski_prison_0b20fc0b/assets/krxzoski-'..choice:lower()..'.wav'
    local option=entry.module.Options.Sounds
    option.List={path};option.ListEnabled={path};option:ChangeValue()
   end)})
   group:CreateButton({Name='Preview sound',Callback=guard(function()
    local opts=entry.module.Options
    local sounds=opts.Sounds and opts.Sounds.ListEnabled or {}
    assert(#sounds>0,'Add a sound asset ID to Sounds first.')
    local id=tostring(sounds[1]):match('^%s*(.-)%s*$')
    if id:match('^%d+$') then id='rbxassetid://'..id end
    if not id:match('^rbxasset') then
     assert(type(getcustomasset)=='function' and isfile(id),'Sound file does not exist')
     id=getcustomasset(id)
    end
    local sound=Instance.new('Sound')
    sound.SoundId=id;sound.Volume=opts.Volume and opts.Volume.Value or 1
    sound.Parent=game:GetService('SoundService')
    game:GetService('Debris'):AddItem(sound,15)
    sound:Play()
    task.delay(5,function()
     if sound.Parent and not sound.IsLoaded then
      bridge:Notify('Sound unavailable','Use an audio ID available to this experience.',8,'Warning')
     end
    end)
   end)})
  end
  if (entry.name=='PlayerAura' or entry.name=='CharacterSkin') and entry.module.Bind then entry.module.Bind:SetBind({},true) end
  if entry.module.Bind and entry.name~='PlayerAura' and entry.name~='CharacterSkin' then
   local b=entry.module.Bind
   input(group,'Keybind',table.concat(b.Keys or {},'+'),function(text)
    local keys=parseKeybind(text)
    b:SetBind(keys,true)
   end)
   group:CreateToggle({Name='Hold keybind',CurrentValue=b.Hold,Callback=function(v) b.Hold=v end})
  end
  self.Count=self.Count+1
 end
