	local function createDownloader(text)
		if vape.Loaded ~= true then
			local downloader = vape.Downloader
			if not downloader then
				downloader = Instance.new('TextLabel')
				downloader.BackgroundTransparency = 1
				downloader.FontFace = uipallet.Font
				downloader.Size = UDim2.new(1, 0, 0, 40)
				downloader.TextColor3 = Color3.new(1, 1, 1)
				downloader.TextSize = 20
				downloader.TextStrokeTransparency = 0
				downloader.Parent = vape.gui
				vape.Downloader = downloader
			end

			downloader.Text = 'Downloading '..text
		end
	end

	local function downloadFile(path, callback)
		if not isfile(path) then
			createDownloader(path)

			local success, data = pcall(function()
				return game:HttpGet('https://raw.githubusercontent.com/7GrandDadPGN/VapeCompiled/'..readfile('krxzoski_prison_0b20fc0b/profiles/commit.txt')..'/'..select(1, path:gsub('krxzoski_prison_0b20fc0b/', '')), true)
			end)

			if not success or data == '404: Not Found' then
				error(data)
			end

			if path:find('.lua') then
				data = '--This watermark is used to delete the file if its cached, remove it to make the file persist after krxzoski updates.\n'..data
			end

			writefile(path, data)
		end

		return (callback or readfile)(path)
	end

	getvapeasset = false and function(path)
		return downloadFile(path, getcustomasset)
	end or function(path)
		return vapeAssets[path] or ''
	end
end

local tween = setmetatable({}, {
	__index = function()
		return {}
	end
})

do
	function tween:Tween(obj, info, goal, index)
		index = self[index or 'tweens']
		if index[obj] then
			index[obj]:Cancel()
			index[obj] = nil
		end

		if obj.Parent and (obj:IsA('UIStroke') or obj.Visible) then
			index[obj] = tweenService:Create(obj, info, goal)
			index[obj].Completed:Once(function()
				if index then
					index[obj] = nil
					index = nil
				end
			end)

			index[obj]:Play()
		else
			for prop, value in goal do
				obj[prop] = value
			end
		end
	end

	function tween:Cancel(obj, index)
		index = self[index or 'tweens']

		if index[obj] then
			index[obj]:Cancel()
			index[obj] = nil
		end
	end
end

