					end)
				end
			end
		
			if #keys <= 0 then
				label.Visible = false
				icon.Visible = true
				bind.Size = UDim2.fromOffset(20, 20)
		
				local index = table.find(vape.ActiveBinds, component)
				if index then
					table.remove(vape.ActiveBinds, index)
