		function component:Save(data)
			data.Main = {
				Position = {
					X = window.Position.X.Offset,
					Y = window.Position.Y.Offset
				},
				Settings = {}
			}
		
			for name, pane in vape.Settings do
				pane:Save(data.Main.Settings)
			end
		end
		
