			if name == 'Custom color' then
				local reset = Instance.new('TextButton')
				reset.BackgroundTransparency = 1
				reset.FontFace = uipallet.Font
				reset.Position = UDim2.new(1, -52, 0, 5)
				reset.Size = UDim2.fromOffset(45, 20)
