			end
		else
			if tail then
				local final_blocks = table.create(3)  
				final_blocks[1] = tail
				final_blocks[2] = "\128"
				final_blocks[3] = string.rep("\0", (-17 - length) % 128 + 9)

				tail = nil
				 
				 
				length = length * (8 / TWO56_POW_7)  
				for j = 4, 10 do
					length = length % 1 * 256
