 local function clear()
  if connection then connection:Disconnect();connection=nil end
  if folder then folder:Destroy();folder=nil end
  if attachment then attachment:Destroy();attachment=nil;emitter=nil;boundRoot=nil end
  parts={}
 end
 local function start()
  clear()
  folder=Instance.new('Folder');folder.Name='krxzoski_aura';folder.Parent=workspace
  for i=1,32 do
   local p=Instance.new('Part');p.Name='Glow';p.Shape=Enum.PartType.Ball
   p.Anchored=true;p.CanCollide=false;p.CanTouch=false;p.CanQuery=false;p.CastShadow=false
   p.Material=Enum.Material.Neon;p.Transparency=1;p.Parent=folder;parts[i]=p
   if i<=8 then
    local a=Instance.new('Attachment');a.Position=Vector3.new(0,0.1,0);a.Parent=p
    local b=Instance.new('Attachment');b.Position=Vector3.new(0,-0.1,0);b.Parent=p
    local trail=Instance.new('Trail');trail.Name='Wake';trail.Attachment0=a;trail.Attachment1=b;trail.Lifetime=0.22;trail.LightEmission=1;trail.FaceCamera=true
    trail.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0.15),NumberSequenceKeypoint.new(1,1)});trail.Parent=p
   end
   local billboard=Instance.new('BillboardGui');billboard.Name='Symbol';billboard.Size=UDim2.fromOffset(28,28);billboard.AlwaysOnTop=false;billboard.Enabled=false;billboard.Parent=p
   local text=Instance.new('TextLabel');text.Size=UDim2.fromScale(1,1);text.BackgroundTransparency=1;text.Font=Enum.Font.GothamBold;text.TextScaled=true;text.TextStrokeTransparency=0.8;text.Parent=billboard
  end
  connection=runService.RenderStepped:Connect(function()
   local character=lplr.Character
   local root=character and character:FindFirstChild('HumanoidRootPart')
   local humanoid=character and character:FindFirstChildOfClass('Humanoid')
   local preset=presets[Style.Value] or presets.Lightning
   local alive=root and humanoid and humanoid.Health>0
   if root~=boundRoot then
    if attachment then attachment:Destroy() end
    attachment=nil;emitter=nil;boundRoot=root
    if root then
     attachment=Instance.new('Attachment');attachment.Name='krxzoski_aura';attachment.Position=Vector3.new(0,-1.8,0);attachment.Parent=root
     emitter=Instance.new('ParticleEmitter');emitter.Name='Atmosphere';emitter.SpreadAngle=Vector2.new(45,45);emitter.Rotation=NumberRange.new(-180,180);emitter.RotSpeed=NumberRange.new(-35,35);emitter.Drag=1;emitter.Parent=attachment
    end
   end
   local count=math.floor(Intensity.Value)
   local t=os.clock()*Speed.Value*preset[3]
   local tint=UseColor.Enabled and Color3.fromHSV(Color.Hue,Color.Sat,Color.Value) or preset[1]
   if emitter then
    local smoke=preset[2]=='Smoke';local fire=Style.Value=='Fire'
    emitter.Enabled=alive and (smoke or fire or Style.Value=='Freeze' or Style.Value=='Shine') or false
    emitter.Texture=fire and 'rbxasset://textures/particles/fire_main.dds' or smoke and 'rbxasset://textures/particles/smoke_main.dds' or 'rbxasset://textures/particles/sparkles_main.dds'
    emitter.Rate=count*(fire and 2 or 1);emitter.Lifetime=NumberRange.new(0.6,1.3);emitter.Speed=NumberRange.new(1.4*Speed.Value,3.2*Speed.Value)
    emitter.Acceleration=Vector3.new(0,fire and 3 or 0.5,0);emitter.LightEmission=smoke and 0.05 or 0.8
    emitter.Color=ColorSequence.new(tint,fire and Color3.fromRGB(255,195,40) or tint:Lerp(Color3.new(1,1,1),0.3))
    emitter.Size=NumberSequence.new({NumberSequenceKeypoint.new(0,Radius.Value*0.45),NumberSequenceKeypoint.new(0.5,Radius.Value*0.7),NumberSequenceKeypoint.new(1,0)})
    emitter.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(0.15,1-Opacity.Value*0.65),NumberSequenceKeypoint.new(1,1)})
   end
   for i,p in ipairs(parts) do
    local symbol=p.Symbol;local wake=p:FindFirstChild('Wake')
    symbol.Enabled=false;if wake then wake.Enabled=false end
    if not alive or i>count then p.Transparency=1
    else
     local phase=i/count*math.pi*2
     local angle=phase+t
     local radius=Radius.Value
     local y=math.sin(t+phase)*0.8
     local size=0.13+0.09*(1+math.sin(t*2+phase))
     local mode=preset[2]
     if mode=='Rise' or mode=='Smoke' or mode=='Bubble' then y=((t*0.7+i/count*5)%5)-2;radius=radius*(0.55+(y+2)/10)
     elseif mode=='Fall' then y=3-((t+i/count*6)%6)
     elseif mode=='Halo' then y=2.8+math.sin(t+phase)*0.15
     elseif mode=='Lightning' then angle=phase+math.floor(t*12)*0.24;y=math.sin(angle*3)*1.8;size=0.16 end
     if mode=='Smoke' then size=0.65+(y+2)*0.12 end
     if mode=='Bubble' then size=0.3+0.18*math.sin(phase+t) end
     local position=root.Position+Vector3.new(math.cos(angle)*radius,y,math.sin(angle)*radius)
     p.Material=mode=='Bubble' and Enum.Material.Glass or (mode=='Smoke' and Enum.Material.SmoothPlastic or Enum.Material.Neon)
     p.Shape=mode=='Lightning' and Enum.PartType.Block or Enum.PartType.Ball
     p.Size=mode=='Lightning' and Vector3.new(0.09,0.09,0.65) or Vector3.new(size,size,size)
     p.CFrame=CFrame.new(position)*CFrame.Angles(t+phase,phase,t)
     p.Color=tint
     p.Transparency=math.clamp(1-Opacity.Value+(mode=='Smoke' and 0.35 or 0)+0.12*math.sin(t*2+phase),0,0.95)
     if mode=='Smoke' or Style.Value=='Fire' then p.Transparency=1 end
     if wake then wake.Enabled=mode=='Lightning' or mode=='Orbit' or Style.Value=='Meteor';wake.Color=ColorSequence.new(tint) end
     local glyph=Style.Value=='Healing' and '+' or Style.Value=='Sleep' and 'Z' or Style.Value=='Soap' and '○' or Style.Value=='Shine' and '✦'
     if glyph then
      p.Transparency=1;symbol.Enabled=i<=math.min(count,10)
      symbol.TextLabel.Text=glyph;symbol.TextLabel.TextColor3=tint;symbol.TextLabel.TextTransparency=math.clamp(1-Opacity.Value+0.18*math.sin(t+phase),0,1)
     end
    end
   end
  end)
 end
 Aura=krxzoskiModule(vape.Categories.Render,'Aura',{Name='PlayerAura',Function=function(on) if on then start() else clear() end end,Tooltip='Animated local character effects. Other players do not see these.'})
 Style=Aura:CreateDropdown({Name='Style',List={'Lightning','Fire','Water','White','Soap','Smoke','Sleep','Shine','Meteor','Healing','Gold','Freeze','Darkness','Blood','Acid'}})
 Radius=Aura:CreateSlider({Name='Radius',Min=1,Max=6,Default=2.5,Decimal=10})
 Speed=Aura:CreateSlider({Name='Speed',Min=0.1,Max=3,Default=1,Decimal=10})
 Intensity=Aura:CreateSlider({Name='Intensity',Min=4,Max=32,Default=20})
 Opacity=Aura:CreateSlider({Name='Opacity',Min=0.1,Max=1,Default=0.8,Decimal=10})
 UseColor=Aura:CreateToggle({Name='Custom color'})
 Color=Aura:CreateColorSlider({Name='Color',DefaultHue=0.52})
end)

run(function()
 local Effects,Style,Color,Size,Duration,Count
 local folder,connection
 local bursts={}
 local target,health,expires
 local function clear()
  if connection then connection:Disconnect();connection=nil end
  if folder then folder:Destroy();folder=nil end
  table.clear(bursts);target=nil;expires=0
 end
 local function burst(position)
  if not folder or #bursts>=8 then return end
  local entry={Time=os.clock(),Life=Duration.Value,Parts={},Position=position}
  local flash=Instance.new('Part');flash.Name='Impact';flash.Anchored=true;flash.CanCollide=false;flash.CanTouch=false;flash.CanQuery=false;flash.Transparency=1;flash.Size=Vector3.new(0.1,0.1,0.1);flash.Position=position;flash.Parent=folder
  local sparks=Instance.new('ParticleEmitter');sparks.Texture='rbxasset://textures/particles/sparkles_main.dds';sparks.Rate=0;sparks.LightEmission=1;sparks.Color=ColorSequence.new(Color3.fromHSV(Color.Hue,Color.Sat,Color.Value));sparks.Speed=NumberRange.new(2,6);sparks.Drag=4;sparks.SpreadAngle=Vector2.new(180,180);sparks.Lifetime=NumberRange.new(0.15,Duration.Value);sparks.Size=NumberSequence.new(0.15*Size.Value,0);sparks.Transparency=NumberSequence.new(0.15,1);sparks.Parent=flash;sparks:Emit(math.floor(Count.Value))
  local light=Instance.new('PointLight');light.Color=Color3.fromHSV(Color.Hue,Color.Sat,Color.Value);light.Brightness=1.5;light.Range=5;light.Parent=flash
  tweenService:Create(light,TweenInfo.new(0.16),{Brightness=0}):Play()
  game:GetService('Debris'):AddItem(flash,Duration.Value+0.2)
  for i=1,math.floor(Count.Value) do
   local p=Instance.new('Part');p.Name='Hit';p.Anchored=true;p.CanCollide=false;p.CanQuery=false;p.CanTouch=false;p.CastShadow=false
   p.Material=Enum.Material.Neon;p.Color=Color3.fromHSV(Color.Hue,Color.Sat,Color.Value)
   p.Shape=Style.Value=='Pixels' and Enum.PartType.Block or Enum.PartType.Ball
   local direction=Style.Value=='Ring' and Vector3.new(math.cos(i/Count.Value*math.pi*2),0,math.sin(i/Count.Value*math.pi*2)) or Vector3.new(math.random()-0.5,math.random()-0.3,math.random()-0.5).Unit
   local size=Size.Value*0.16;p.Size=Vector3.new(size,size,size);p.Position=position;p.Parent=folder
   table.insert(entry.Parts,{Part=p,Direction=direction,Size=size})
  end
  table.insert(bursts,entry)
 end
 local function start()
  clear();folder=Instance.new('Folder');folder.Name='krxzoski_hits';folder.Parent=workspace
  connection=runService.RenderStepped:Connect(function()
   for i=#bursts,1,-1 do
    local b=bursts[i];local a=(os.clock()-b.Time)/b.Life
    if a>=1 then for _,p in ipairs(b.Parts) do p.Part:Destroy() end;table.remove(bursts,i)
    else for _,p in ipairs(b.Parts) do
     p.Part.Position=b.Position+p.Direction*a*Size.Value*3
     p.Part.Transparency=a
     local size=math.max(0.02,p.Size*(1-a));p.Part.Size=Vector3.new(size,size,size)
    end end
   end
  end)
 end
 Effects=krxzoskiModule(vape.Categories.Render,'Effects',{Name='HitEffects',Function=function(on)
  if on then
   start()
   TracerHook:Add('krxzoski_hit_effects',function()
    local part=debug.getstack(4,13)
    if typeof(part)~='Instance' then return end
    for _,entity in entitylib.List do
     if part:IsDescendantOf(entity.Character) and entitylib.isVulnerable(entity,true) then
      if entity~=target or (expires or 0)<os.clock() then health=entity.Health end
      target=entity;expires=os.clock()+0.5;break
     end
    end
   end)
   Effects:Clean(entitylib.Events.EntityUpdated:Connect(function(entity)
    if entity==target and (expires or 0)>os.clock() then
     if health and entity.Health<health and entity.RootPart then burst(entity.RootPart.Position) end
     health=entity.Health
    end
   end))
  else TracerHook:Remove('krxzoski_hit_effects');clear() end
 end,Tooltip='Bursts when a recent gun hit is followed by damage.'})
 Style=Effects:CreateDropdown({Name='Style',List={'Sparks','Ring','Pixels'}})
 Color=Effects:CreateColorSlider({Name='Color',DefaultHue=0.52})
 Size=Effects:CreateSlider({Name='Size',Min=0.5,Max=3,Default=1,Decimal=10})
 Duration=Effects:CreateSlider({Name='Duration',Min=0.2,Max=1.5,Default=0.5,Decimal=10})
 Count=Effects:CreateSlider({Name='Particles',Min=4,Max=24,Default=12})
 function Effects:Preview()
  if not self.Enabled then self:Toggle() end
  local character=lplr.Character;local root=character and character:FindFirstChild('HumanoidRootPart')
  assert(root,'Spawn into the game to preview effects')
  burst(root.Position+root.CFrame.LookVector*4)
 end
end)

run(function()
 local Skin,Preset,Asset,Scale,Offset
 local model,connection,character,hideConnection,physicsConnection
 local physicsGuards={}
 local hidden,poses={},{}
 local token=0
 local function clear()
  if connection then connection:Disconnect();connection=nil end
  if hideConnection then hideConnection:Disconnect();hideConnection=nil end
  if physicsConnection then physicsConnection:Disconnect();physicsConnection=nil end
  for _,guard in ipairs(physicsGuards) do guard:Disconnect() end
  table.clear(physicsGuards)
  if model then model:Destroy();model=nil end
  for part,value in pairs(hidden) do if part.Parent then part.LocalTransparencyModifier=value end end
  table.clear(hidden);table.clear(poses);character=nil
 end
 local function alert(text)
  local ui=shared.BVCSteelBridge;if ui then ui:Notify('Character skin',text,6,'Warning') end
 end
 local function builtIn(name,char)
  local result=Instance.new('Model');result.Name=name
  for _,part in ipairs(char:GetChildren()) do
   if part:IsA('BasePart') and part.Name~='HumanoidRootPart' then
    local item=Instance.new('Part');item.Name=part.Name;item.Size=part.Size;item.CFrame=part.CFrame
    item.Color=name=='Robot' and Color3.fromRGB(75,90,110) or Color3.fromRGB(25,12,42)
    item.Material=name=='Robot' and Enum.Material.Metal or Enum.Material.SmoothPlastic
    item.Parent=result
    if part.Name=='Head' then
     local visor=Instance.new('Part');visor.Name='Visor';visor.Size=Vector3.new(part.Size.X*0.75,0.16,0.08)
     visor.CFrame=part.CFrame*CFrame.new(0,0.12,-part.Size.Z/2-0.02)
     visor.Color=name=='Robot' and Color3.fromRGB(35,240,255) or Color3.fromRGB(215,80,255)
     visor.Material=Enum.Material.Neon;visor.Parent=result
    end
   end
  end
  return result
 end
 local aliases={UpperTorso='Torso',LowerTorso='Torso',LeftUpperArm='Left Arm',LeftLowerArm='Left Arm',LeftHand='Left Arm',RightUpperArm='Right Arm',RightLowerArm='Right Arm',RightHand='Right Arm',LeftUpperLeg='Left Leg',LeftLowerLeg='Left Leg',LeftFoot='Left Leg',RightUpperLeg='Right Leg',RightLowerLeg='Right Leg',RightFoot='Right Leg'}
 local function lockPart(part)
  if not part.Anchored then part.Anchored=true end
  if part.CanCollide then part.CanCollide=false end
  if part.CanTouch then part.CanTouch=false end
  if part.CanQuery then part.CanQuery=false end
  part.Massless=true
 end
 local function sanitize(candidate)
  local descendants=candidate:GetDescendants()
  assert(#descendants<=2500,'Model is too complex (2,500 objects maximum)')
  local count=0
  for _,item in ipairs(descendants) do
   if item:IsA('BasePart') then
    count=count+1;item.Anchored=true;item.CanCollide=false;item.CanTouch=false;item.CanQuery=false;item.CastShadow=false
    item.LocalTransparencyModifier=0
    item.AssemblyLinearVelocity=Vector3.zero;item.AssemblyAngularVelocity=Vector3.zero
    lockPart(item)
    for _,property in ipairs({'CanCollide','Anchored','CanTouch'}) do
     table.insert(physicsGuards,item:GetPropertyChangedSignal(property):Connect(function() if item.Parent then lockPart(item) end end))
    end
   elseif item:IsA('Humanoid') then
    item.RequiresNeck=false;item.BreakJointsOnDeath=false;item.AutoRotate=false;item.PlatformStand=true
    item.DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None
    pcall(function() item.EvaluateStateMachine=false end)
    for _,state in ipairs(Enum.HumanoidStateType:GetEnumItems()) do
     if state~=Enum.HumanoidStateType.None then pcall(function() item:SetStateEnabled(state,false) end) end
    end
   elseif not (item:IsA('Model') or item:IsA('Folder') or item:IsA('Accessory') or item:IsA('DataModelMesh') or item:IsA('Decal') or item:IsA('Texture') or item:IsA('SurfaceAppearance') or item:IsA('Attachment') or item:IsA('Clothing') or item:IsA('ShirtGraphic') or item:IsA('BodyColors') or item:IsA('WrapLayer') or item:IsA('WrapTarget') or item:IsA('Bone') or item:IsA('JointInstance')) then
    item:Destroy()
   end
  end
  assert(count>0 and count<=200,'Model must contain 1–200 visible parts')
 end
 local function apply()
  token=token+1;local request=token
  clear()
  local char=lplr.Character;local root=char and char:FindFirstChild('HumanoidRootPart')
  if not root then alert('Spawn into a team before applying a skin.');return end
  local candidate,donor
  local korblox={}
  local ok,err=pcall(function()
   local name=Preset.Value
   if name=='Robot' or name=='Shadow' then candidate=builtIn(name,char)
   elseif name=='krxzoski special' then
    local humanoid=char:FindFirstChildOfClass('Humanoid')
    local description=playersService:GetHumanoidDescriptionFromUserIdAsync(7309924316)
    description.RightLeg=139607718
    description.HeightScale=1;description.WidthScale=1;description.DepthScale=1;description.HeadScale=1;description.BodyTypeScale=0;description.ProportionScale=0
    candidate=playersService:CreateHumanoidModelFromDescriptionAsync(description,Enum.HumanoidRigType.R6)
    donor=playersService:CreateHumanoidModelFromDescriptionAsync(description,Enum.HumanoidRigType.R15)
    description:Destroy()
    candidate.Name='krxzoski_special'
    local leg=candidate:FindFirstChild('Right Leg')
    local donorRoot=donor:FindFirstChild('HumanoidRootPart')
    assert(leg and donorRoot,'Korblox leg could not be prepared')
    local function legBounds()
     local low,high=Vector3.new(math.huge,math.huge,math.huge),Vector3.new(-math.huge,-math.huge,-math.huge)
     for _,partName in ipairs({'RightUpperLeg','RightLowerLeg','RightFoot'}) do
      local part=donor:FindFirstChild(partName);assert(part and part:IsA('BasePart'),'Korblox geometry is unavailable')
      local point=donorRoot.CFrame:PointToObjectSpace(part.Position);local half=part.Size/2
      low=Vector3.new(math.min(low.X,point.X-half.X),math.min(low.Y,point.Y-half.Y),math.min(low.Z,point.Z-half.Z))
      high=Vector3.new(math.max(high.X,point.X+half.X),math.max(high.Y,point.Y+half.Y),math.max(high.Z,point.Z+half.Z))
     end
     return low,high
    end
    local low,high=legBounds()
    donor:ScaleTo(donor:GetScale()*leg.Size.Y/(high.Y-low.Y))
    low,high=legBounds()
    local center=donorRoot.CFrame*CFrame.new((low+high)/2)
    local assembly=Instance.new('Model');assembly.Name='krxzoski_right_leg';assembly.Parent=candidate
    for _,partName in ipairs({'RightUpperLeg','RightLowerLeg','RightFoot'}) do
     local part=donor:FindFirstChild(partName):Clone()
     for _,child in ipairs(part:GetDescendants()) do if child:IsA('JointInstance') or child:IsA('LuaSourceContainer') then child:Destroy() end end
     local offset=center:ToObjectSpace(part.CFrame)
     part.CFrame=leg.CFrame*offset;part.Parent=assembly
     table.insert(korblox,{Part=part,Offset=offset})
    end
    leg.Transparency=1
    donor:Destroy();donor=nil
   else
    local id=name=='Shrek' and '5132836159' or tostring(Asset.Value):match('^%s*(%d+)%s*$')
    assert(id,'Enter a numeric Roblox model asset ID')
    local objects=game:GetObjects('rbxassetid://'..id)
    for _,object in ipairs(objects) do
     if not candidate and object:IsA('Model') then candidate=object else object:Destroy() end
    end
    assert(candidate,'This asset does not contain a usable model')
   end
   sanitize(candidate)
   assert(request==token and Skin.Enabled and lplr.Character==char,'Skin loading cancelled')
   local function bodyHeight(rig)
    local low,high=math.huge,-math.huge
    for _,part in ipairs(rig:GetChildren()) do
     if part:IsA('BasePart') and part.Name~='HumanoidRootPart' and (part.Name=='Head' or part.Name=='Torso' or aliases[part.Name] or part.Name:find(' Arm',1,true) or part.Name:find(' Leg',1,true)) then
      low=math.min(low,part.Position.Y-part.Size.Y/2);high=math.max(high,part.Position.Y+part.Size.Y/2)
     end
    end
    if high<=low then local _,size=rig:GetBoundingBox();return size.Y end
    return high-low
   end
   local height=bodyHeight(candidate)
   assert(height>0.05 and height<10000,'Model size is invalid')
   local nativeR6=name=='krxzoski special'
   if nativeR6 then
    for _,partName in ipairs({'Head','Torso','Left Arm','Right Arm','Left Leg','Right Leg'}) do
     assert(candidate:FindFirstChild(partName) and char:FindFirstChild(partName),'krxzoski special needs a spawned R6 character')
    end
   end
   candidate:ScaleTo(candidate:GetScale()*(nativeR6 and Scale.Value or math.clamp(bodyHeight(char)/height*Scale.Value,0.01,100)))
   local bounds=candidate:GetBoundingBox()
   candidate:PivotTo(root.CFrame*CFrame.new(0,Offset.Value,0)*bounds:ToObjectSpace(candidate:GetPivot()))
   local groups={}
   for _,part in ipairs(candidate:GetChildren()) do
    if part:IsA('BasePart') and part.Name~='HumanoidRootPart' then
     local targetName=char:FindFirstChild(part.Name) and part.Name or aliases[part.Name]
     if targetName and char:FindFirstChild(targetName) then
      groups[targetName]=groups[targetName] or {};table.insert(groups[targetName],part)
     end
    end
   end
   local groupFrames={}
   local rigRoot=candidate:FindFirstChild('HumanoidRootPart')
   local reference=rigRoot and rigRoot.CFrame or candidate:GetPivot()
   local sourceJoints={}
   for _,joint in ipairs(char:GetDescendants()) do
    if joint:IsA('Motor6D') then sourceJoints[joint.Name]=joint end
   end
   local jointNames={Root='RootJoint',RightShoulder='Right Shoulder',LeftShoulder='Left Shoulder',RightHip='Right Hip',LeftHip='Left Hip'}
   local links={}
   for _,joint in ipairs(candidate:GetDescendants()) do
    if joint:IsA('JointInstance') then
     if joint.Part0 and joint.Part1 and joint.Part0:IsDescendantOf(candidate) and joint.Part1:IsDescendantOf(candidate) then
      table.insert(links,{A=joint.Part0,B=joint.Part1,C0=joint.C0,C1=joint.C1,Driver=sourceJoints[joint.Name] or sourceJoints[jointNames[joint.Name] or '']})
     end
     joint:Destroy()
    end
   end
   local function updatePose()
    local frames={}
    if nativeR6 then
     for _,part in ipairs(candidate:GetChildren()) do
      local actual=char:FindFirstChild(part.Name)
      if part:IsA('BasePart') and actual and actual:IsA('BasePart') then
       local relative=root.CFrame:ToObjectSpace(actual.CFrame)
       frames[part]=root.CFrame*CFrame.new(0,Offset.Value,0)*CFrame.new(relative.Position*Scale.Value)*relative.Rotation
      end
     end
     local leg=candidate:FindFirstChild('Right Leg')
     local legFrame=leg and frames[leg]
     if legFrame then
      for _,piece in ipairs(korblox) do
       frames[piece.Part]=legFrame*CFrame.new(piece.Offset.Position*Scale.Value)*piece.Offset.Rotation
      end
     end
    end
    if rigRoot and #links>0 then
     frames[rigRoot]=root.CFrame*CFrame.new(0,Offset.Value,0)
     for _=1,#links do
      local changed=false
      for _,link in ipairs(links) do
       if (frames[link.A] and not frames[link.B]) or (frames[link.B] and not frames[link.A]) then
        local motion=CFrame.new()
        local driver=link.Driver
        if not nativeR6 and driver and driver.Parent and driver.Part0 and driver.Part1 then
         local relative=driver.Part0.CFrame:ToObjectSpace(driver.Part1.CFrame)
         local delta=driver.C0:Inverse()*relative*driver.C1
         local rotation=driver.C0.Rotation*delta.Rotation*driver.C0.Rotation:Inverse()
         motion=link.C0.Rotation:Inverse()*rotation*link.C0.Rotation
        end
        local relative=link.C0*motion*link.C1:Inverse()
        if frames[link.A] then frames[link.B]=frames[link.A]*relative
        else frames[link.A]=frames[link.B]*relative:Inverse() end
        changed=true
       end
      end
      if not changed then break end
     end
    end
    for _,pose in ipairs(poses) do
     local anchor=char:FindFirstChild(pose.Name) or root
     if pose.Part.Parent then pose.Part.CFrame=frames[pose.Part] or anchor.CFrame*pose.Offset end
    end
   end
